606	    private String executeArgs(ProfilerAction action) {
607	        StringBuilder sb = new StringBuilder();
608	        final char COMMA = ',';
609	
610	        // start - start profiling
611	        // resume - start or resume profiling without resetting collected data
612	        // stop - stop profiling
613	        sb.append(action).append(COMMA);
614	
615	        if (this.event != null) {
616	            sb.append("event=").append(this.event).append(COMMA);
617	        }
618	        if (this.alloc!= null) {
619	            sb.append("alloc=").append(this.alloc).append(COMMA);
620	        }
621	        if (this.live) {
622	            sb.append("live").append(COMMA);
623	        }
624	        if (this.lock!= null) {
625	            sb.append("lock=").append(this.lock).append(COMMA);
626	        }
627	        if (this.jfrsync != null) {
628	            this.format = "jfr";
629	            sb.append("jfrsync=").append(this.jfrsync).append(COMMA);
630	        }
631	        boolean markdown = isMarkdownFormat();
632	        // md 是 Arthas 侧的后处理格式，不应传递给 async-profiler（避免识别失败/输出到文件导致数据丢失等问题）
633	        boolean passFile = this.file != null;
634	        if (markdown && (action == ProfilerAction.start || action == ProfilerAction.resume)) {
635	            passFile = false;
636	        }
637	        if (passFile) {
638	            sb.append("file=").append(this.file).append(COMMA);
639	        }
640	        if (this.format != null && !markdown) {
641	            sb.append(this.format).append(COMMA);
642	        }
643	        if (this.interval != null) {
644	            sb.append("interval=").append(this.interval).append(COMMA);
645	        }
646	        if (this.features != null) {
647	            sb.append("features=").append(this.features).append(COMMA);
648	        }
649	        if (this.signal != null) {
650	            sb.append("signal=").append(this.signal).append(COMMA);
651	        }
652	        if (this.clock != null) {
653	            sb.append("clock=").append(this.clock).append(COMMA);
654	        }
655	        if (this.jstackdepth != null) {
656	            sb.append("jstackdepth=").append(this.jstackdepth).append(COMMA);
657	        }
658	        if (this.threads) {
659	            sb.append("threads").append(COMMA);
660	        }
661	        if (this.sched) {
662	            sb.append("sched").append(COMMA);
663	        }
664	        if (this.cstack != null) {
665	            sb.append("cstack=").append(this.cstack).append(COMMA);
666	        }
667	        if (this.simple) {
668	            sb.append("simple").append(COMMA);
669	        }
670	        if (this.sig) {
671	            sb.append("sig").append(COMMA);
672	        }
673	        if (this.ann) {
674	            sb.append("ann").append(COMMA);
675	        }
676	        if (this.lib) {
677	            sb.append("lib").append(COMMA);
678	        }
679	        if (this.alluser) {
680	            sb.append("alluser").append(COMMA);
681	        }
682	        if (this.norm) {
683	            sb.append("norm").append(COMMA);
684	        }
685	        if (this.includes != null) {
686	            for (String include : includes) {
687	                sb.append("include=").append(include).append(COMMA);
688	            }
689	        }
690	        if (this.excludes != null) {
691	            for (String exclude : excludes) {
692	                sb.append("exclude=").append(exclude).append(COMMA);
693	            }
694	        }
695	        if (this.ttsp) {
696	            this.begin = "SafepointSynchronize::begin";
697	            this.end = "RuntimeService::record_safepoint_synchronized";
698	        }
699	        if (this.begin != null) {
700	            sb.append("begin=").append(this.begin).append(COMMA);
701	        }
702	        if (this.end != null) {
703	            sb.append("end=").append(this.end).append(COMMA);
704	        }
705	        if (this.wall != null) {
706	            sb.append("wall=").append(this.wall).append(COMMA);
707	        }
708	        if (this.title != null) {
709	            sb.append("title=").append(this.title).append(COMMA);
710	        }
711	        if (this.minwidth != null) {
712	            sb.append("minwidth=").append(this.minwidth).append(COMMA);
713	        }
714	        if (this.reverse) {
715	            sb.append("reverse").append(COMMA);
716	        }
717	        if (this.total) {
718	            sb.append("total").append(COMMA);
719	        }
720	        if (this.chunksize != null) {
721	            sb.append("chunksize=").append(this.chunksize).append(COMMA);
722	        }
723	        if (this.chunktime!= null) {
724	            sb.append("chunktime=").append(this.chunktime).append(COMMA);
725	        }
726	        if (this.loop != null) {
727	            sb.append("loop=").append(this.loop).append(COMMA);
728	        }
729	        if (this.timeout != null) {
730	            sb.append("timeout=").append(this.timeout).append(COMMA);
731	        }
732	
733	        return sb.toString();
734	    }
735	
736	    private static String execute(AsyncProfiler asyncProfiler, String arg)
737	            throws IllegalArgumentException, IOException {
738	        logger.info("profiler execute args: {}", arg);
739	        String result = asyncProfiler.execute(arg);
740	        if (!result.endsWith("\n")) {
741	            result += "\n";
742	        }
743	        return result;
744	    }
745	
746	    @Override
747	    public void process(final CommandProcess process) {
748	        try {
749	            ProfilerAction profilerAction = ProfilerAction.valueOf(action);
750	
751	            if (ProfilerAction.actions.equals(profilerAction)) {
752	                process.appendResult(new ProfilerModel(actions()));
753	                process.end();
754	                return;
755	            }
756	
757	            final AsyncProfiler asyncProfiler = this.profilerInstance();
758	
759	            if (ProfilerAction.execute.equals(profilerAction)) {
760	                if (actionArg == null) {
761	                    process.end(1, "actionArg can not be empty.");
762	                    return;
763	                }
764	                String result = execute(asyncProfiler, this.actionArg);
765	                appendExecuteResult(process, result);
766	            } else if (ProfilerAction.start.equals(profilerAction)) {
767	                // Track if file parameter was specified during start
768	                boolean autoGeneratedFile = false;
769	                if (this.file != null) {
770	                    fileSpecifiedAtStart = this.file;
771	                    logger.debug("File specified during profiler start: {}", fileSpecifiedAtStart);
772	                } else if (this.timeout != null) {
773	                    // Auto-generate file if timeout is specified but file is not
774	                    try {
775	                        this.file = outputFile();
776	                        logger.debug("Auto-generated file for timeout: {}", this.file);
777	                        fileSpecifiedAtStart = this.file;
778	                        autoGeneratedFile = true;
779	                    } catch (IOException e) {
780	                        logger.warn("Failed to auto-generate file for timeout", e);
781	                    }
782	                }
783	
784	                if (this.duration == null) {
785	                    String executeArgs = executeArgs(ProfilerAction.start);
786	                    String result = execute(asyncProfiler, executeArgs);
787	                    ProfilerModel profilerModel = createProfilerModel(result);
788	
789	                    // Add information about auto-generated file for timeout
790	                    if (autoGeneratedFile && this.file != null) {
791	                        profilerModel.setOutputFile(this.file);
792	                        profilerModel.setExecuteResult(profilerModel.getExecuteResult()
793	                                + "\nAuto-generated output file will be: " + this.file + "\n");
794	                    }
795	
796	                    process.appendResult(profilerModel);
797	                } else { // 设置延时执行 stop
798	                    final String outputFile = outputFile();
799	                    String executeArgs = executeArgs(ProfilerAction.start);
800	                    String result = execute(asyncProfiler, executeArgs);
801	                    ProfilerModel profilerModel = createProfilerModel(result);
802	                    profilerModel.setOutputFile(outputFile);
803	                    profilerModel.setDuration(duration);
804	
805	                    // 延时执行stop
806	                    ArthasBootstrap.getInstance().getScheduledExecutorService().schedule(new Runnable() {
807	                        @Override
808	                        public void run() {
809	                            // 在异步线程执行，profiler命令已经结束，不能输出到客户端
810	                            try {
811	                                logger.info("stopping profiler ...");
812	                                ProfilerModel model = processStop(asyncProfiler, ProfilerAction.stop);
813	                                logger.info("profiler output file: " + model.getOutputFile());
814	                                logger.info("stop profiler successfully.");
815	                            } catch (Throwable e) {
816	                                logger.error("stop profiler failure", e);
817	                            }
818	                        }
819	                    }, this.duration, TimeUnit.SECONDS);
820	                    process.appendResult(profilerModel);
821	                }
822	
823	            } else if (ProfilerAction.stop.equals(profilerAction)) {
824	                ProfilerModel profilerModel = processStop(asyncProfiler, profilerAction);
825	                process.appendResult(profilerModel);
826	            } else if (ProfilerAction.dump.equals(profilerAction)) {
827	                ProfilerModel profilerModel = processStop(asyncProfiler, profilerAction);
828	                process.appendResult(profilerModel);
829	            } else if (ProfilerAction.resume.equals(profilerAction)) {
830	                String executeArgs = executeArgs(ProfilerAction.resume);
831	                String result = execute(asyncProfiler, executeArgs);
832	                appendExecuteResult(process, result);
833	            } else if (ProfilerAction.version.equals(profilerAction)) {
834	                String result = asyncProfiler.execute("version=full");
835	                appendExecuteResult(process, result);
836	            } else if (ProfilerAction.status.equals(profilerAction)
837	                    || ProfilerAction.meminfo.equals(profilerAction)
838	                    || ProfilerAction.list.equals(profilerAction)) {
839	                String result = asyncProfiler.execute(profilerAction.toString());
840	                appendExecuteResult(process, result);
841	            } else if (ProfilerAction.dumpCollapsed.equals(profilerAction)) {
842	                if (actionArg == null) {
843	                    actionArg = "TOTAL";
844	                }
845	                actionArg = actionArg.toUpperCase();
846	                if ("TOTAL".equals(actionArg) || "SAMPLES".equals(actionArg)) {
847	                    String result = asyncProfiler.dumpCollapsed(Counter.valueOf(actionArg));
848	                    appendExecuteResult(process, result);
849	                } else {
850	                    process.end(1, "ERROR: dumpCollapsed argumment should be TOTAL or SAMPLES. ");
851	                    return;
852	                }
853	            } else if (ProfilerAction.dumpFlat.equals(profilerAction)) {
854	                int maxMethods = 0;
855	                if (actionArg != null) {
856	                    maxMethods = Integer.valueOf(actionArg);
857	                }
858	                String result = asyncProfiler.dumpFlat(maxMethods);
859	                appendExecuteResult(process, result);
860	            } else if (ProfilerAction.dumpTraces.equals(profilerAction)) {
861	                int maxTraces = 0;
862	                if (actionArg != null) {
863	                    maxTraces = Integer.valueOf(actionArg);
864	                }
865	                String result = asyncProfiler.dumpTraces(maxTraces);
866	                appendExecuteResult(process, result);
867	            } else if (ProfilerAction.getSamples.equals(profilerAction)) {
868	                String result = "" + asyncProfiler.getSamples() + "\n";
869	                appendExecuteResult(process, result);
870	            }
871	            process.end();
872	        } catch (Throwable e) {
873	            logger.error("AsyncProfiler error", e);
874	            process.end(1, "AsyncProfiler error: "+e.getMessage());
875	        }
876	    }
877	
878	    private ProfilerModel processStop(AsyncProfiler asyncProfiler, ProfilerAction profilerAction) throws IOException {
879	        // profiler stop --file xxx.md：自动推断为 Markdown 输出
880	        if (this.format == null && this.file != null && this.file.toLowerCase().endsWith(".md")) {
881	            this.format = "md";
882	        }
883	
884	        if (isMarkdownFormat() && (profilerAction == ProfilerAction.stop || profilerAction == ProfilerAction.dump)) {
885	            return processStopMarkdown(asyncProfiler, profilerAction);
886	        }
887	
888	        String outputFile = null;
889	
890	        // If we're stopping and a file was specified during start, don't generate a new
891	        // output file
892	        if (profilerAction == ProfilerAction.stop && fileSpecifiedAtStart != null) {
893	            outputFile = fileSpecifiedAtStart;
894	            // Reset the tracking variable after stop
895	            logger.debug("Using file specified during start: {}", fileSpecifiedAtStart);
896	            fileSpecifiedAtStart = null;
897	        } else {
898	            // Otherwise generate or use the specified output file
899	            outputFile = outputFile();
900	        }
901	
902	        String executeArgs = executeArgs(profilerAction);
903	        String result = execute(asyncProfiler, executeArgs);
904	
905	        ProfilerModel profilerModel = createProfilerModel(result);
906	        if (outputFile != null) {
907	            profilerModel.setOutputFile(outputFile);
908	        }
909	        return profilerModel;
910	    }
911	
912	    private ProfilerModel processStopMarkdown(AsyncProfiler asyncProfiler, ProfilerAction profilerAction) throws IOException {
913	        // Markdown 输出：先让 async-profiler 输出 collapsed 文本，再在 Arthas 侧做结构化汇总。
914	        String userFormat = this.format;
915	        String userFile = this.file;
916	        int topN = mdTopN(userFormat);
917	
918	        // stop 时如果 start 阶段指定过 file，需要清理掉，避免影响后续 stop 行为
919	        if (profilerAction == ProfilerAction.stop) {
920	            fileSpecifiedAtStart = null;
921	        }
922	
923	        File collapsedFile = File.createTempFile("arthas-profiler-collapsed", ".txt");
924	        String collapsed;
925	        try {
926	            // 为避免 async-profiler 由于历史 file 配置导致返回 OK 而非 collapsed 文本，这里强制输出到临时文件后再读取。
927	            this.file = collapsedFile.getAbsolutePath();
928	            this.format = "collapsed";
929	
930	            String executeArgs = executeArgs(profilerAction);
931	            execute(asyncProfiler, executeArgs);
932	
933	            collapsed = FileUtils.readFileToString(collapsedFile, StandardCharsets.UTF_8);
934	        } finally {
935	            // best-effort cleanup
936	            try {
937	                collapsedFile.delete();
938	            } catch (Throwable ignore) {
939	                // ignore
940	            }
941	            this.format = userFormat;
942	            this.file = userFile;
943	        }
944	
945	        String markdown = ProfilerMarkdown.toMarkdown(new ProfilerMarkdown.Options()
946	                .action(profilerAction.name())
947	                .event(this.event)
948	                .threads(this.threads)
949	                .topN(topN)
950	                .collapsed(collapsed));
951	
952	        String outputFile = null;
953	        if (userFile != null && !userFile.trim().isEmpty()) {
954	            outputFile = userFile;
955	            FileUtils.writeByteArrayToFile(new File(outputFile), markdown.getBytes(StandardCharsets.UTF_8));
956	        }
957	
958	        ProfilerModel profilerModel = createProfilerModel(markdown);
959	        profilerModel.setFormat(userFormat);
960	        profilerModel.setOutputFile(outputFile);
961	        return profilerModel;
962	    }
963	
964	    private int mdTopN(String format) {
965	        final int defaultTopN = 10;
966	        if (format == null) {
967	            return defaultTopN;
968	        }
969	        String f = format.trim().toLowerCase();
970	        if (!f.startsWith("md")) {
971	            return defaultTopN;
972	        }
973	        int idx = f.indexOf('=');
974	        if (idx < 0 || idx == f.length() - 1) {
975	            return defaultTopN;
976	        }
977	        try {
978	            int n = Integer.parseInt(f.substring(idx + 1).trim());
979	            return n > 0 ? n : defaultTopN;
980	        } catch (Throwable e) {
981	            return defaultTopN;
982	        }
983	    }
984	
985	    private String outputFile() throws IOException {
986	        if (this.file == null) {
987	            String fileExt = outputFileExt();
988	            File outputPath = ArthasBootstrap.getInstance().getOutputPath();
989	            if (outputPath != null) {
990	                this.file = new File(outputPath,
991	                        new SimpleDateFormat("yyyyMMdd-HHmmss").format(new Date()) + "." + fileExt)
992	                                .getAbsolutePath();
993	            } else {
994	                this.file = File.createTempFile("arthas-output", "." + fileExt).getAbsolutePath();
995	            }
996	        }
997	        return file;
998	    }
999	
1000	    /**
1001	     * This method should only be called when {@code this.file == null} is true.
1002	     */
1003	    private String outputFileExt() {
1004	        String fileExt = "";
1005	        if (this.format == null) {
1006	            fileExt = "html";
1007	        } else if (this.format.toLowerCase().startsWith("md")) {
1008	            fileExt = "md";
1009	        } else if (this.format.startsWith("flat") || this.format.startsWith("traces") 
1010	                || this.format.equals("collapsed")) {
1011	            fileExt = "txt";
1012	        } else if (this.format.equals("flamegraph") || this.format.equals("tree")) {
1013	            fileExt = "html";
1014	        } else if (this.format.equals("jfr")) {
1015	            fileExt = "jfr";
1016	        } else {
1017	            // illegal -o option makes async-profiler use flat
1018	            fileExt = "txt";
1019	        }
1020	        return fileExt;
1021	    }
1022	
1023	    private void appendExecuteResult(CommandProcess process, String result) {
1024	        ProfilerModel profilerModel = createProfilerModel(result);
1025	        process.appendResult(profilerModel);
1026	    }
1027	
1028	    private ProfilerModel createProfilerModel(String result) {
1029	        ProfilerModel profilerModel = new ProfilerModel();
1030	        profilerModel.setAction(action);
1031	        profilerModel.setActionArg(actionArg);
1032	        profilerModel.setFormat(format);
1033	        profilerModel.setExecuteResult(result);
1034	        return profilerModel;
1035	    }
