1037	    private List<String> events() {
1038	        List<String> result = new ArrayList<String>();
1039	
1040	        String execute;
1041	        try {
1042	            /**
1043	             * <pre>
1044	               Basic events:
1045	                  cpu
1046	                  alloc
1047	                  lock
1048	                  wall
1049	                  itimer
1050	             * </pre>
1051	             */
1052	            execute = this.profilerInstance().execute("list");
1053	        } catch (Throwable e) {
1054	            // ignore
1055	            return result;
1056	        }
1057	        String lines[] = execute.split("\\r?\\n");
1058	
1059	        for (String line : lines) {
1060	            if (line.startsWith(" ")) {
1061	                result.add(line.trim());
1062	            }
1063	        }
1064	        return result;
