1075	    @Override
1076	    public void complete(Completion completion) {
1077	        List<CliToken> tokens = completion.lineTokens();
1078	        String token = tokens.get(tokens.size() - 1).value();
1079	
1080	        if (tokens.size() >= 2) {
1081	            CliToken cliToken_1 = tokens.get(tokens.size() - 1);
1082	            CliToken cliToken_2 = tokens.get(tokens.size() - 2);
1083	            if (cliToken_1.isBlank()) {
1084	                String token_2 = cliToken_2.value();
1085	                if (token_2.equals("-e") || token_2.equals("--event")) {
1086	                    CompletionUtils.complete(completion, events());
1087	                    return;
1088	                } else if (token_2.equals("-o") || token_2.equals("--format")) {
1089	                    CompletionUtils.complete(completion, Arrays.asList(
1090	                            "flamegraph", "tree", "jfr",
1091	                            "flat", "traces", "collapsed",
1092	                            "md", "md=10"
1093	                    ));
1094	                    return;
1095	                }
1096	            }
1097	        }
1098	
1099	        if (token.startsWith("-")) {
1100	            super.complete(completion);
1101	            return;
1102	        }
1103	
1104	        CompletionUtils.complete(completion, actions());
1105	    }
